/// <summary>
/// Modified event handler of the form data source field
/// </summary>
/// <param name="sender">Target field object</param>
/// <param name="e">EventArgs</param>
[FormDataFieldEventHandler(formDataFieldStr(VendFormletterParameters, VendFormletterParameters, METPurchConfirmationReportDefaultLogo), FormDataFieldEventType::Modified)]
public static void METPurchConfirmationReportDefaultLogo_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    //VendFormletterParameters    vendFormLetterParameters = sender.datasource().cursor();
    METPurchConfirmationReportUseDefaultLogo useDefaultLogo = sender.getValue();
    
    sender.datasource().object(fieldNum(VendFormletterParameters, metPurchConfirmationReportDefaultLogo))
        .allowEdit(useDefaultLogo == NoYes::Yes);
}

/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormDataSourceEventHandler(formDataSourceStr(VendFormletterParameters, VendFormletterParameters), FormDataSourceEventType::Activated)]
public static void VendFormletterParameters_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    VendFormletterParameters    vendFormLetterParameters = sender.cursor();
    
    sender.object(fieldNum(VendFormletterParameters, metPurchConfirmationReportDefaultLogo))
        .allowEdit(vendFormLetterParameters.METPurchConfirmationReportUseDefaultLogo == NoYes::Yes);
}
